/** Cropped artboard of the source logo, in its own units: the drawing padded by the stroke caps. */
private const val VIEWPORT_WIDTH = 1200f
private const val VIEWPORT_HEIGHT = 575f
private const val ORIGIN_X = 160f
private const val ORIGIN_Y = 150f

/**
 * The "Expressive DROID" wordmark. The serif letters take [ink] and the purple accents ('xpressive',
 * the badge standing in for the O and the wave under the E) take [accent], so the logo follows the
 * theme, dynamic color and dark mode instead of being a fixed-color drawable.
 */
@Composable
fun EDroidLogo(
    modifier: Modifier = Modifier,
    ink: Color = MaterialTheme.colorScheme.onSurface,
    accent: Color = MaterialTheme.colorScheme.primary,
) {
    val logo = remember(ink, accent) { logoVector(ink, accent) }
    Image(
        imageVector = logo,
        contentDescription = stringResource(R.string.app_name),
        modifier = modifier.aspectRatio(VIEWPORT_WIDTH / VIEWPORT_HEIGHT),
    )
}

private fun logoVector(ink: Color, accent: Color): ImageVector {
    val inkFill = SolidColor(ink)
    val accentFill = SolidColor(accent)
    return ImageVector.Builder(
        name = "EDroidLogo",
        defaultWidth = VIEWPORT_WIDTH.dp / 4,
        defaultHeight = VIEWPORT_HEIGHT.dp / 4,
        viewportWidth = VIEWPORT_WIDTH,
        viewportHeight = VIEWPORT_HEIGHT,
    ).apply {
        addGroup(translationX = -ORIGIN_X, translationY = -ORIGIN_Y)
        addPath(addPathNodes(XPRESSIVE_PATH), fill = accentFill)
        addPath(addPathNodes(DR_ID_PATH), fill = inkFill)
        addPath(addPathNodes(BADGE_PATH), fill = accentFill)
        addPath(addPathNodes(E_PATH), fill = inkFill)
        addPath(
            addPathNodes(WAVE_PATH),
            stroke = accentFill,
            strokeLineWidth = 13f,
            strokeLineCap = StrokeCap.Round,
            strokeLineJoin = StrokeJoin.Round,
            strokeLineMiter = 10f,
        )
        addPath(
            addPathNodes("M546.5 662.5V717.5"),
            stroke = accentFill,
            strokeLineWidth = 13f,
            strokeLineCap = StrokeCap.Round,
        )
        clearGroup()
    }.build()
}

